CREATE OR REPLACE FUNCTION public.enforce_contact_registered_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_name text;
  v_email text;
BEGIN
  IF NEW.user_id IS NOT NULL THEN
    SELECT full_name, email
    INTO v_name, v_email
    FROM public.profiles
    WHERE id = NEW.user_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Registered support user not found';
    END IF;

    NEW.name := COALESCE(NULLIF(trim(v_name), ''), 'Registered member');
    NEW.email := COALESCE(NULLIF(trim(v_email), ''), NEW.email);
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_start_support_thread(p_user_id uuid, p_message text DEFAULT 'Support opened this conversation to assist you.'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_profile public.profiles%ROWTYPE;
  v_thread_id uuid;
  v_message text := trim(COALESCE(p_message, ''));
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Administrator access required';
  END IF;

  SELECT * INTO v_profile
  FROM public.profiles
  WHERE id = p_user_id
    AND role IN ('driver', 'owner');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Member not found';
  END IF;

  IF char_length(v_message) < 5 OR char_length(v_message) > 5000 THEN
    RAISE EXCEPTION 'Support message must be between 5 and 5000 characters';
  END IF;

  SELECT id INTO v_thread_id
  FROM public.contact_messages
  WHERE user_id = p_user_id
  ORDER BY updated_at DESC
  LIMIT 1;

  IF v_thread_id IS NOT NULL THEN
    RETURN v_thread_id;
  END IF;

  INSERT INTO public.contact_messages (user_id, name, email, message, status)
  VALUES (
    p_user_id,
    COALESCE(NULLIF(trim(v_profile.full_name), ''), 'Registered member'),
    COALESCE(NULLIF(trim(v_profile.email), ''), 'member@drivevell.local'),
    v_message,
    'new'
  )
  RETURNING id INTO v_thread_id;

  RETURN v_thread_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_list_profiles()
 RETURNS SETOF profiles
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Administrator access required';
  END IF;
  RETURN QUERY SELECT * FROM public.profiles ORDER BY created_at DESC;
END;
$function$

CREATE OR REPLACE FUNCTION public.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_driver_available(p_driver_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_role text;
  v_connection_exists boolean;
BEGIN
  -- get caller role
  SELECT role INTO v_caller_role FROM public.profiles WHERE id = auth.uid();

  IF v_caller_role = 'admin' THEN
    -- admin can always mark available
    UPDATE public.profiles SET availability = 'available' WHERE id = p_driver_id AND role = 'driver';
    RETURN;
  END IF;

  IF v_caller_role <> 'owner' THEN
    RAISE EXCEPTION 'Only car owners or admins can mark a driver as available';
  END IF;

  -- owner must have an accepted or ended connection with this driver
  SELECT EXISTS (
    SELECT 1 FROM public.connections
    WHERE status IN ('accepted', 'ended')
      AND (
        (requester_id = p_driver_id AND recipient_id = auth.uid())
        OR (recipient_id = p_driver_id AND requester_id = auth.uid())
      )
  ) INTO v_connection_exists;

  IF NOT v_connection_exists THEN
    RAISE EXCEPTION 'No connection found between you and this driver';
  END IF;

  UPDATE public.profiles SET availability = 'available' WHERE id = p_driver_id AND role = 'driver';
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_delete_user(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT is_admin() THEN
    RAISE EXCEPTION 'Only admins can delete users';
  END IF;
  IF p_user_id = auth.uid() THEN
    RAISE EXCEPTION 'Cannot delete your own admin account';
  END IF;

  -- Delete user's related data
  DELETE FROM messages WHERE sender_id = p_user_id;
  DELETE FROM notifications WHERE user_id = p_user_id;
  DELETE FROM documents WHERE user_id = p_user_id;
  DELETE FROM driver_platform_history WHERE driver_id = p_user_id;
  DELETE FROM reports WHERE reporter_id = p_user_id;
  DELETE FROM favorites WHERE user_id = p_user_id;
  DELETE FROM blocks WHERE blocker_id = p_user_id OR blocked_id = p_user_id;
  DELETE FROM reviews WHERE reviewer_id = p_user_id OR reviewee_id = p_user_id;

  -- Delete vehicles and their children
  DELETE FROM vehicle_photos WHERE vehicle_id IN (SELECT id FROM vehicles WHERE owner_id = p_user_id);
  DELETE FROM vehicle_issues WHERE vehicle_id IN (SELECT id FROM vehicles WHERE owner_id = p_user_id);
  DELETE FROM vehicles WHERE owner_id = p_user_id;

  -- Delete conversations involving the user
  DELETE FROM messages WHERE conversation_id IN (
    SELECT id FROM conversations WHERE driver_id = p_user_id OR owner_id = p_user_id
  );
  DELETE FROM conversations WHERE driver_id = p_user_id OR owner_id = p_user_id;

  -- Delete connections
  DELETE FROM connections WHERE requester_id = p_user_id OR recipient_id = p_user_id;

  -- Delete profile
  DELETE FROM profiles WHERE id = p_user_id;

  -- Finally delete from auth.users
  DELETE FROM auth.users WHERE id = p_user_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_vehicle_featured()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin() AND NEW.featured IS DISTINCT FROM OLD.featured THEN
    RAISE EXCEPTION 'Featured status is administrator-only';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.transition_connection(p_connection_id uuid, p_status text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_conn public.connections%ROWTYPE;
  v_requester_role text;
  v_recipient_role text;
  v_driver_id uuid;
  v_owner_id uuid;
  v_conversation_id uuid;
BEGIN
  SELECT * INTO v_conn FROM public.connections WHERE id = p_connection_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Connection not found'; END IF;
  IF v_conn.status <> 'pending' THEN RAISE EXCEPTION 'Connection is no longer pending'; END IF;

  IF p_status IN ('accepted', 'rejected') AND auth.uid() <> v_conn.recipient_id THEN
    RAISE EXCEPTION 'Only the recipient can accept or reject';
  ELSIF p_status = 'withdrawn' AND auth.uid() <> v_conn.requester_id THEN
    RAISE EXCEPTION 'Only the requester can withdraw';
  ELSIF p_status NOT IN ('accepted', 'rejected', 'withdrawn') THEN
    RAISE EXCEPTION 'Invalid connection status';
  END IF;

  -- Serialize acceptances involving either participant so two simultaneous
  -- clicks cannot create overlapping active connections.
  IF p_status = 'accepted' THEN
    PERFORM 1 FROM public.profiles
    WHERE id IN (v_conn.requester_id, v_conn.recipient_id)
    ORDER BY id FOR UPDATE;
  END IF;

  IF p_status = 'accepted' AND (
    EXISTS (
      SELECT 1 FROM public.connections c
      WHERE c.status = 'accepted'
        AND (v_conn.requester_id IN (c.requester_id, c.recipient_id)
          OR v_conn.recipient_id IN (c.requester_id, c.recipient_id))
    ) OR EXISTS (
      SELECT 1 FROM public.applications a
      WHERE a.status = 'accepted'
        AND (v_conn.requester_id IN (a.driver_id, a.owner_id)
          OR v_conn.recipient_id IN (a.driver_id, a.owner_id))
    )
  ) THEN
    RAISE EXCEPTION 'One of these members is already on an active connection. End it before accepting another.';
  END IF;

  UPDATE public.connections SET status = p_status WHERE id = v_conn.id;

  IF p_status = 'accepted' THEN
    SELECT role INTO v_requester_role FROM public.profiles WHERE id = v_conn.requester_id;
    SELECT role INTO v_recipient_role FROM public.profiles WHERE id = v_conn.recipient_id;
    IF v_requester_role = 'driver' THEN v_driver_id := v_conn.requester_id; END IF;
    IF v_recipient_role = 'driver' THEN v_driver_id := v_conn.recipient_id; END IF;
    IF v_requester_role = 'owner' THEN v_owner_id := v_conn.requester_id; END IF;
    IF v_recipient_role = 'owner' THEN v_owner_id := v_conn.recipient_id; END IF;
    IF v_driver_id IS NULL OR v_owner_id IS NULL THEN
      RAISE EXCEPTION 'Connections must pair one driver with one owner';
    END IF;

    UPDATE public.profiles SET availability = 'busy'
    WHERE id IN (v_conn.requester_id, v_conn.recipient_id);

    INSERT INTO public.conversations (connection_id, vehicle_id, driver_id, owner_id)
    VALUES (v_conn.id, v_conn.vehicle_id, v_driver_id, v_owner_id)
    ON CONFLICT (connection_id) DO UPDATE
      SET connection_id = EXCLUDED.connection_id, closed_at = NULL, closed_by = NULL
    RETURNING id INTO v_conversation_id;
  END IF;

  INSERT INTO public.notifications (user_id, type, title, body, data)
  VALUES (
    CASE WHEN auth.uid() = v_conn.requester_id THEN v_conn.recipient_id ELSE v_conn.requester_id END,
    'connection_' || p_status,
    'Connection ' || p_status,
    CASE WHEN p_status = 'accepted'
      THEN 'Your connection request was accepted. Both profiles now show currently on a connection, and neither member can accept another until this connection ends.'
      ELSE 'Your connection request was ' || p_status || '.' END,
    jsonb_build_object('connection_id', v_conn.id, 'conversation_id', v_conversation_id)
  );
  RETURN v_conversation_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_vehicle_photo_moderation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin() AND (
    NEW.approved IS DISTINCT FROM OLD.approved OR
    NEW.rejected IS DISTINCT FROM OLD.rejected OR
    NEW.rejection_reason IS DISTINCT FROM OLD.rejection_reason
  ) THEN
    RAISE EXCEPTION 'Vehicle-photo moderation is administrator-only';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_my_availability_before_history_gate(p_available boolean)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_conn record; v_app record; v_count integer := 0; v_name text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF NOT p_available THEN
    UPDATE public.profiles SET availability = 'unavailable' WHERE id = auth.uid() AND role IN ('driver','owner');
    RETURN 0;
  END IF;
  SELECT full_name INTO v_name FROM public.profiles WHERE id = auth.uid();
  FOR v_conn IN SELECT * FROM public.connections WHERE status = 'accepted' AND auth.uid() IN (requester_id, recipient_id) FOR UPDATE LOOP
    UPDATE public.connections SET status = 'ended' WHERE id = v_conn.id;
    UPDATE public.conversations SET closed_at = now(), closed_by = auth.uid() WHERE connection_id = v_conn.id AND closed_at IS NULL;
    INSERT INTO public.notifications (user_id, type, title, body, data)
    VALUES (CASE WHEN auth.uid() = v_conn.requester_id THEN v_conn.recipient_id ELSE v_conn.requester_id END,
      'connection_ended', 'Connection ended', COALESCE(v_name, 'The other member') || ' became available for new connections and ended your active connection. The chat remains saved as read-only history.', jsonb_build_object('connection_id', v_conn.id));
    PERFORM public.refresh_member_availability(v_conn.requester_id);
    PERFORM public.refresh_member_availability(v_conn.recipient_id);
    v_count := v_count + 1;
  END LOOP;
  FOR v_app IN SELECT * FROM public.applications WHERE status = 'accepted' AND auth.uid() IN (driver_id, owner_id) FOR UPDATE LOOP
    UPDATE public.applications SET status = 'completed' WHERE id = v_app.id;
    UPDATE public.conversations SET closed_at = now(), closed_by = auth.uid() WHERE application_id = v_app.id AND closed_at IS NULL;
    INSERT INTO public.notifications (user_id, type, title, body, data)
    VALUES (CASE WHEN auth.uid() = v_app.driver_id THEN v_app.owner_id ELSE v_app.driver_id END,
      'connection_ended', 'Connection ended', COALESCE(v_name, 'The other member') || ' became available for new connections. The chat remains saved as read-only history.', jsonb_build_object('application_id', v_app.id));
    PERFORM public.refresh_member_availability(v_app.driver_id);
    PERFORM public.refresh_member_availability(v_app.owner_id);
    v_count := v_count + 1;
  END LOOP;
  PERFORM public.refresh_member_availability(auth.uid());
  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_profile_verification()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id=auth.uid() AND role='driver' AND NOT is_suspended AND onboarding_completed) THEN RAISE EXCEPTION 'Complete About You with an active driver account first'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('history-' || auth.uid()::text,0));
  -- Idempotent retry: do not repeat notifications or overwrite a pending review.
  IF EXISTS (SELECT 1 FROM public.driver_platform_history WHERE driver_id=auth.uid() AND review_status='pending') THEN RETURN; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.driver_platform_history WHERE driver_id=auth.uid() AND review_status='draft') THEN RAISE EXCEPTION 'No new or renewed proof to submit'; END IF;
  IF EXISTS (SELECT 1 FROM public.driver_platform_history WHERE driver_id=auth.uid() AND review_status='draft' AND (months_active < 1 OR NULLIF(trim(proof_url),'') IS NULL)) THEN RAISE EXCEPTION 'Add months active and upload proof for every draft platform, or remove unused draft entries'; END IF;
  PERFORM set_config('app.history_transition','on',true);
  UPDATE public.driver_platform_history SET review_status='pending',submitted_at=now(),approved=false WHERE driver_id=auth.uid() AND review_status='draft';
  PERFORM set_config('app.history_transition','off',true);
  INSERT INTO public.notifications(user_id,type,title,body,data)
    SELECT id,'trust','Platform history ready for review','A driver submitted platform history. Review their private proof.',jsonb_build_object('path','/admin?tab=history') FROM public.profiles WHERE role='admin' AND NOT is_suspended;
END;
$function$

CREATE OR REPLACE FUNCTION public.recalculate_profile_rating(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_review_average numeric;
  v_review_count integer;
  v_upheld_reports integer;
  v_rating numeric;
BEGIN
  SELECT COALESCE(round(avg(r.rating)::numeric, 1), 5.0), count(*)::integer
  INTO v_review_average, v_review_count
  FROM public.reviews r
  WHERE r.reviewee_id = p_user_id;

  SELECT count(*)::integer INTO v_upheld_reports
  FROM public.reports
  WHERE reported_id = p_user_id AND status IN ('reviewing', 'resolved');

  v_rating := greatest(1.0, round((v_review_average - (v_upheld_reports * 0.1))::numeric, 1));
  PERFORM set_config('app.profile_system_update', 'on', true);
  UPDATE public.profiles
  SET rating = v_rating, rating_count = v_review_count
  WHERE id = p_user_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.recalculate_rating_after_report()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.reported_id IS NOT NULL THEN PERFORM public.recalculate_profile_rating(OLD.reported_id); END IF;
    RETURN OLD;
  END IF;
  IF NEW.reported_id IS NOT NULL THEN PERFORM public.recalculate_profile_rating(NEW.reported_id); END IF;
  IF TG_OP = 'UPDATE' AND OLD.reported_id IS DISTINCT FROM NEW.reported_id AND OLD.reported_id IS NOT NULL THEN
    PERFORM public.recalculate_profile_rating(OLD.reported_id);
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_review(p_application_id uuid, p_rating integer, p_content text DEFAULT NULL::text)
 RETURNS reviews
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_app public.applications%ROWTYPE;
  v_reviewee uuid;
  v_review public.reviews%ROWTYPE;
BEGIN
  IF p_rating NOT BETWEEN 1 AND 5 THEN RAISE EXCEPTION 'Rating must be between 1 and 5'; END IF;
  SELECT * INTO v_app FROM public.applications WHERE id = p_application_id;
  IF NOT FOUND OR v_app.status NOT IN ('accepted', 'completed') THEN
    RAISE EXCEPTION 'A completed match is required to leave a review';
  END IF;
  IF auth.uid() = v_app.driver_id THEN v_reviewee := v_app.owner_id;
  ELSIF auth.uid() = v_app.owner_id THEN v_reviewee := v_app.driver_id;
  ELSE RAISE EXCEPTION 'Not an application participant';
  END IF;

  INSERT INTO public.reviews (application_id, reviewer_id, reviewee_id, rating, content)
  VALUES (v_app.id, auth.uid(), v_reviewee, p_rating, nullif(trim(p_content), ''))
  RETURNING * INTO v_review;

  PERFORM public.recalculate_profile_rating(v_reviewee);
  PERFORM set_config('app.profile_system_update', 'on', true);
  UPDATE public.profiles p SET contracts_completed = (
    SELECT count(*) FROM public.applications a
    WHERE a.status = 'completed' AND (a.driver_id = p.id OR a.owner_id = p.id)
  ) WHERE p.id = v_reviewee;
  RETURN v_review;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_vehicle_approval_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF public.is_admin() OR current_setting('app.vehicle_resubmission', true) = 'on' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.approval_status := 'pending';
    NEW.approval_note := NULL;
    NEW.approved_at := NULL;
    NEW.approved_by := NULL;
    RETURN NEW;
  END IF;

  NEW.approval_status := OLD.approval_status;
  NEW.approval_note := OLD.approval_note;
  NEW.approved_at := OLD.approved_at;
  NEW.approved_by := OLD.approved_by;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.end_connection(p_connection_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_conn public.connections%ROWTYPE; v_other uuid; v_name text;
BEGIN
  SELECT * INTO v_conn FROM public.connections WHERE id = p_connection_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Connection not found'; END IF;
  IF auth.uid() NOT IN (v_conn.requester_id, v_conn.recipient_id) AND NOT public.is_admin() THEN RAISE EXCEPTION 'Not a connection participant'; END IF;
  IF v_conn.status <> 'accepted' THEN RAISE EXCEPTION 'Only accepted connections can be ended'; END IF;
  UPDATE public.connections SET status = 'ended' WHERE id = v_conn.id;
  UPDATE public.conversations SET closed_at = now(), closed_by = auth.uid() WHERE connection_id = v_conn.id AND closed_at IS NULL;
  v_other := CASE WHEN auth.uid() = v_conn.requester_id THEN v_conn.recipient_id ELSE v_conn.requester_id END;
  SELECT full_name INTO v_name FROM public.profiles WHERE id = auth.uid();
  INSERT INTO public.notifications (user_id, type, title, body, data)
  VALUES (v_other, 'connection_ended', 'Connection ended', COALESCE(v_name, 'The other member') || ' ended the connection. The chat is saved as read-only history; send a new connection request to chat again.', jsonb_build_object('connection_id', v_conn.id));
  PERFORM public.refresh_member_availability(v_conn.requester_id);
  PERFORM public.refresh_member_availability(v_conn.recipient_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.refresh_driver_history_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid := CASE WHEN TG_OP='DELETE' THEN OLD.driver_id ELSE NEW.driver_id END;
BEGIN
  PERFORM set_config('app.profile_system_update','on',true);
  UPDATE public.profiles SET platform_history_approved=false,platform_history_submitted=false WHERE id=v_id;
  UPDATE public.profiles SET is_verified=platform_history_approved,
    verification_status=CASE WHEN platform_history_submitted THEN 'pending' WHEN platform_history_approved THEN 'approved' WHEN EXISTS(SELECT 1 FROM public.driver_platform_history WHERE driver_id=v_id AND review_status='rejected') THEN 'rejected' ELSE 'unverified' END WHERE id=v_id AND role='driver';
  PERFORM set_config('app.profile_system_update','off',true);
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.derive_driver_history_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.platform_history_approved := NEW.role='driver' AND EXISTS (SELECT 1 FROM public.driver_platform_history WHERE driver_id=NEW.id AND review_status='approved' AND approved AND expires_at>now() AND proof_url IS NOT NULL AND months_active>0);
  NEW.platform_history_submitted := NEW.role='driver' AND EXISTS (SELECT 1 FROM public.driver_platform_history WHERE driver_id=NEW.id AND review_status='pending');
  NEW.platform_history_valid_until := (SELECT max(expires_at) FROM public.driver_platform_history WHERE driver_id=NEW.id AND review_status='approved' AND approved AND proof_url IS NOT NULL AND months_active>0);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_join_conversation(p_conversation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_conversation public.conversations%ROWTYPE;
  v_inserted integer;
  v_was_closed boolean;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Administrator access required'; END IF;

  SELECT * INTO v_conversation
  FROM public.conversations
  WHERE id = p_conversation_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Conversation not found'; END IF;
  IF v_conversation.driver_id IS NULL OR v_conversation.owner_id IS NULL THEN
    RAISE EXCEPTION 'Direct support messages belong in Messages';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.reports report
    WHERE report.target_type = 'conversation'
      AND report.target_id = p_conversation_id
      AND report.reason = 'Support requested'
  ) THEN
    RAISE EXCEPTION 'Support has not been invited to this conversation';
  END IF;

  v_was_closed := v_conversation.closed_at IS NOT NULL;
  INSERT INTO public.conversation_admins (conversation_id, admin_id)
  VALUES (p_conversation_id, auth.uid())
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  IF v_was_closed THEN
    UPDATE public.conversations
    SET closed_at = NULL,
        closed_by = NULL,
        support_reopened_at = now(),
        support_reopened_by = auth.uid(),
        support_resolved_at = NULL,
        support_reopened_from_member_end = (
          v_conversation.admin_closed_at IS NULL
          AND v_conversation.closed_by IN (v_conversation.driver_id, v_conversation.owner_id)
        ),
        admin_closed_at = NULL,
        admin_closed_by = NULL
    WHERE id = p_conversation_id;

    INSERT INTO public.messages (conversation_id, sender_id, content, type)
    VALUES (
      p_conversation_id,
      auth.uid(),
      'Support reopened this ended chat. Both members can message again while the support session is active.',
      'system'
    );
  ELSIF v_inserted > 0 THEN
    INSERT INTO public.messages (conversation_id, sender_id, content, type)
    VALUES (
      p_conversation_id,
      auth.uid(),
      'An administrator joined this conversation to provide support and help resolve concerns.',
      'system'
    );
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.send_message(p_conversation_id uuid, p_content text)
 RETURNS messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_message public.messages%ROWTYPE;
  v_conversation public.conversations%ROWTYPE;
  v_joined_admin boolean := false;
  v_direct_participant boolean := false;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;

  SELECT * INTO v_conversation FROM public.conversations WHERE id = p_conversation_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Conversation not found'; END IF;

  v_direct_participant := auth.uid() = v_conversation.driver_id
    OR auth.uid() = v_conversation.owner_id
    OR auth.uid() = v_conversation.admin_id;
  SELECT EXISTS (
    SELECT 1 FROM public.conversation_admins ca
    WHERE ca.conversation_id = p_conversation_id AND ca.admin_id = auth.uid()
  ) INTO v_joined_admin;

  IF NOT v_direct_participant AND NOT v_joined_admin THEN
    RAISE EXCEPTION 'You are not a participant in this conversation';
  END IF;
  IF v_conversation.closed_at IS NOT NULL THEN
    RAISE EXCEPTION 'This chat is read-only. An administrator can reopen it when support is needed.';
  END IF;

  IF auth.uid() IN (v_conversation.driver_id, v_conversation.owner_id)
     AND EXISTS (
       SELECT 1 FROM public.blocks b
       WHERE b.blocker_id = auth.uid()
         AND b.blocked_id = CASE WHEN auth.uid() = v_conversation.driver_id THEN v_conversation.owner_id ELSE v_conversation.driver_id END
     ) THEN
    RAISE EXCEPTION 'You blocked this member. Unblock them before sending a message.';
  END IF;

  IF auth.uid() IN (v_conversation.driver_id, v_conversation.owner_id)
     AND EXISTS (
       SELECT 1 FROM public.blocks b
       WHERE b.blocked_id = auth.uid()
         AND b.blocker_id = CASE WHEN auth.uid() = v_conversation.driver_id THEN v_conversation.owner_id ELSE v_conversation.driver_id END
     ) THEN
    RAISE EXCEPTION 'This member has blocked messaging with you.';
  END IF;

  IF length(trim(COALESCE(p_content, ''))) = 0 THEN RAISE EXCEPTION 'Message cannot be empty'; END IF;
  IF length(trim(p_content)) > 1000 THEN RAISE EXCEPTION 'Message must be 1000 characters or fewer'; END IF;

  INSERT INTO public.messages (conversation_id, sender_id, content, type)
  VALUES (p_conversation_id, auth.uid(), trim(p_content), 'text')
  RETURNING * INTO v_message;
  RETURN v_message;
END;
$function$

CREATE OR REPLACE FUNCTION public.transition_application(p_application_id uuid, p_status text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_app public.applications%ROWTYPE; v_conversation_id uuid;
BEGIN
  SELECT * INTO v_app FROM public.applications WHERE id = p_application_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Application not found'; END IF;
  IF p_status IN ('accepted', 'rejected', 'completed') THEN
    IF auth.uid() <> v_app.owner_id AND NOT public.is_admin() THEN RAISE EXCEPTION 'Only the vehicle owner can perform this transition'; END IF;
  ELSIF p_status = 'withdrawn' THEN
    IF auth.uid() <> v_app.driver_id THEN RAISE EXCEPTION 'Only the driver can withdraw an application'; END IF;
  ELSE RAISE EXCEPTION 'Invalid application status'; END IF;
  IF v_app.status <> 'pending' AND NOT (v_app.status = 'accepted' AND p_status = 'completed') THEN
    RAISE EXCEPTION 'Invalid application transition from % to %', v_app.status, p_status;
  END IF;

  IF p_status = 'accepted' THEN
    PERFORM 1 FROM public.profiles
    WHERE id IN (v_app.driver_id, v_app.owner_id)
    ORDER BY id FOR UPDATE;
  END IF;

  IF p_status = 'accepted' AND (
    EXISTS (
      SELECT 1 FROM public.connections c
      WHERE c.status = 'accepted'
        AND (v_app.driver_id IN (c.requester_id, c.recipient_id)
          OR v_app.owner_id IN (c.requester_id, c.recipient_id))
    ) OR EXISTS (
      SELECT 1 FROM public.applications a
      WHERE a.status = 'accepted'
        AND a.id <> v_app.id
        AND (v_app.driver_id IN (a.driver_id, a.owner_id)
          OR v_app.owner_id IN (a.driver_id, a.owner_id))
    )
  ) THEN
    RAISE EXCEPTION 'One of these members is already on an active connection. End it before accepting another.';
  END IF;

  UPDATE public.applications SET status = p_status WHERE id = v_app.id;
  IF p_status = 'accepted' THEN
    UPDATE public.profiles SET availability = 'busy' WHERE id IN (v_app.driver_id, v_app.owner_id);
    INSERT INTO public.conversations (application_id, vehicle_id, driver_id, owner_id)
    VALUES (v_app.id, v_app.vehicle_id, v_app.driver_id, v_app.owner_id)
    ON CONFLICT (application_id) DO UPDATE
      SET application_id = EXCLUDED.application_id, closed_at = NULL, closed_by = NULL
    RETURNING id INTO v_conversation_id;
  ELSIF p_status = 'completed' THEN
    UPDATE public.conversations SET closed_at = now(), closed_by = auth.uid()
    WHERE application_id = v_app.id AND closed_at IS NULL;
    PERFORM public.refresh_member_availability(v_app.driver_id);
    PERFORM public.refresh_member_availability(v_app.owner_id);
  END IF;
  INSERT INTO public.notifications (user_id, type, title, body, data)
  VALUES (
    v_app.driver_id,
    'application_' || p_status,
    'Application ' || p_status,
    CASE
      WHEN p_status = 'accepted' THEN 'Your application was accepted. Both profiles now show currently on a connection, and neither member can accept another until this arrangement ends.'
      WHEN p_status = 'completed' THEN 'The arrangement was completed. Your chat remains saved as read-only history.'
      ELSE 'Your application was ' || p_status || '.'
    END,
    jsonb_build_object('application_id', v_app.id, 'conversation_id', v_conversation_id)
  );
  RETURN v_conversation_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.touch_my_last_seen()
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_seen_at timestamptz := now();
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  UPDATE public.profiles SET last_seen_at = v_seen_at WHERE id = auth.uid();
