$function$

CREATE OR REPLACE FUNCTION public.get_conversation_block_status(p_conversation_id uuid)
 RETURNS TABLE(i_blocked_other boolean, blocked_by_other boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_conversation public.conversations%ROWTYPE;
  v_other_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT * INTO v_conversation
  FROM public.conversations
  WHERE id = p_conversation_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Conversation not found';
  END IF;

  IF auth.uid() = v_conversation.driver_id THEN
    v_other_id := v_conversation.owner_id;
  ELSIF auth.uid() = v_conversation.owner_id THEN
    v_other_id := v_conversation.driver_id;
  ELSE
    RAISE EXCEPTION 'Only conversation members can view block status';
  END IF;

  RETURN QUERY SELECT
    EXISTS (
      SELECT 1 FROM public.blocks b
      WHERE b.blocker_id = auth.uid() AND b.blocked_id = v_other_id
    ),
    EXISTS (
      SELECT 1 FROM public.blocks b
      WHERE b.blocker_id = v_other_id AND b.blocked_id = auth.uid()
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.request_conversation_support(p_conversation_id uuid, p_message text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_conversation public.conversations%ROWTYPE;
  v_other_id uuid;
  v_report_id uuid;
  v_requester_name text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF length(trim(COALESCE(p_message, ''))) < 10 THEN
    RAISE EXCEPTION 'Tell support what help you need using at least 10 characters';
  END IF;
  IF length(trim(p_message)) > 1000 THEN RAISE EXCEPTION 'Support request must be 1000 characters or fewer'; END IF;

  SELECT * INTO v_conversation
  FROM public.conversations
  WHERE id = p_conversation_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Conversation not found'; END IF;
  IF v_conversation.driver_id IS NULL OR v_conversation.owner_id IS NULL
     OR auth.uid() NOT IN (v_conversation.driver_id, v_conversation.owner_id) THEN
    RAISE EXCEPTION 'Only a member of this connection chat can request support';
  END IF;

  v_other_id := CASE
    WHEN auth.uid() = v_conversation.driver_id THEN v_conversation.owner_id
    ELSE v_conversation.driver_id
  END;

  SELECT id INTO v_report_id
  FROM public.reports
  WHERE reporter_id = auth.uid()
    AND target_type = 'conversation'
    AND target_id = p_conversation_id
    AND reason = 'Support requested'
    AND status IN ('open', 'reviewing')
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_report_id IS NOT NULL THEN RETURN v_report_id; END IF;

  INSERT INTO public.reports (reporter_id, reported_id, target_type, target_id, reason, description)
  VALUES (auth.uid(), v_other_id, 'conversation', p_conversation_id, 'Support requested', trim(p_message))
  RETURNING id INTO v_report_id;

  SELECT full_name INTO v_requester_name FROM public.profiles WHERE id = auth.uid();
  INSERT INTO public.notifications (user_id, type, title, body, data)
  SELECT p.id,
         'support_request',
         'Support requested for a connection chat',
         COALESCE(v_requester_name, 'A member') || ' asked for help with a specific conversation.',
         jsonb_build_object(
           'path', '/admin?tab=reports',
           'conversation_id', p_conversation_id,
           'report_id', v_report_id
         )
  FROM public.profiles p
  WHERE p.role = 'admin' AND NOT p.is_suspended;

  RETURN v_report_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_close_conversation_chat(p_conversation_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_conversation public.conversations%ROWTYPE;
  v_reopened_support_session boolean;
  v_has_member_support_request boolean;
  v_resolution_message boolean;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Administrator access required'; END IF;

  SELECT * INTO v_conversation
  FROM public.conversations
  WHERE id = p_conversation_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Conversation not found'; END IF;
  IF v_conversation.driver_id IS NULL OR v_conversation.owner_id IS NULL THEN
    RAISE EXCEPTION 'Only a member connection chat can be closed with this action';
  END IF;
  IF v_conversation.closed_at IS NOT NULL THEN RAISE EXCEPTION 'This chat is already closed'; END IF;

  v_reopened_support_session := v_conversation.support_reopened_at IS NOT NULL
    AND v_conversation.support_resolved_at IS NULL;
  SELECT EXISTS (
    SELECT 1 FROM public.reports r
    WHERE r.target_type = 'conversation'
      AND r.target_id = p_conversation_id
      AND r.reason = 'Support requested'
  ) INTO v_has_member_support_request;
  v_resolution_message := v_reopened_support_session
    AND v_conversation.support_reopened_from_member_end
    AND v_has_member_support_request;

  IF v_resolution_message THEN
    INSERT INTO public.messages (conversation_id, sender_id, content, type)
    VALUES (
      p_conversation_id,
      auth.uid(),
      'Support marked this matter as resolved. The chat is read-only again, and the complete history remains saved.',
      'system'
    );
  ELSE
    INSERT INTO public.messages (conversation_id, sender_id, content, type)
    VALUES (
      p_conversation_id,
      auth.uid(),
      'An administrator closed this chat. Members can no longer send new messages, and the complete history remains saved.',
      'system'
    );
  END IF;

  UPDATE public.conversations
  SET closed_at = now(),
      closed_by = auth.uid(),
      support_resolved_at = CASE WHEN v_reopened_support_session THEN now() ELSE support_resolved_at END,
      admin_closed_at = now(),
      admin_closed_by = auth.uid()
  WHERE id = p_conversation_id;

  IF v_resolution_message THEN
    UPDATE public.reports
    SET status = 'resolved'
    WHERE target_type = 'conversation'
      AND target_id = p_conversation_id
      AND reason = 'Support requested'
      AND status IN ('open', 'reviewing');
  END IF;

  RETURN CASE WHEN v_resolution_message THEN 'support_resolved' ELSE 'admin_closed' END;
END;
$function$

CREATE OR REPLACE FUNCTION public.send_chat_image(p_conversation_id uuid, p_path text)
 RETURNS messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_message public.messages%ROWTYPE;
  v_conversation public.conversations%ROWTYPE;
  v_joined_admin boolean := false;
  v_direct_participant boolean := false;
  v_expected_prefix text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;

  SELECT * INTO v_conversation FROM public.conversations WHERE id = p_conversation_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Conversation not found'; END IF;

  v_direct_participant := auth.uid() = v_conversation.driver_id
    OR auth.uid() = v_conversation.owner_id
    OR auth.uid() = v_conversation.admin_id;
  SELECT EXISTS (
    SELECT 1 FROM public.conversation_admins ca
    WHERE ca.conversation_id = p_conversation_id AND ca.admin_id = auth.uid()
  ) INTO v_joined_admin;

  IF NOT v_direct_participant AND NOT v_joined_admin THEN
    RAISE EXCEPTION 'You are not a participant in this conversation';
  END IF;
  IF v_conversation.closed_at IS NOT NULL THEN
    RAISE EXCEPTION 'This chat is read-only. An administrator can reopen it when support is needed.';
  END IF;

  IF auth.uid() IN (v_conversation.driver_id, v_conversation.owner_id)
     AND v_conversation.driver_id IS NOT NULL
     AND v_conversation.owner_id IS NOT NULL
     AND EXISTS (
       SELECT 1 FROM public.blocks b
       WHERE (b.blocker_id = v_conversation.driver_id AND b.blocked_id = v_conversation.owner_id)
          OR (b.blocker_id = v_conversation.owner_id AND b.blocked_id = v_conversation.driver_id)
     ) THEN
    RAISE EXCEPTION 'Messaging is unavailable because one member blocked the other';
  END IF;

  v_expected_prefix := p_conversation_id::text || '/' || auth.uid()::text || '/';
  IF p_path IS NULL
     OR length(p_path) > 500
     OR position('..' IN p_path) > 0
     OR left(p_path, length(v_expected_prefix)) <> v_expected_prefix
     OR right(lower(p_path), 4) <> '.jpg' THEN
    RAISE EXCEPTION 'Invalid chat image path';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM storage.objects
    WHERE bucket_id = 'chat-media' AND name = p_path AND owner_id = auth.uid()::text
  ) THEN
    RAISE EXCEPTION 'Chat image upload was not found';
  END IF;

  INSERT INTO public.messages (conversation_id, sender_id, content, type)
  VALUES (p_conversation_id, auth.uid(), p_path, 'image')
  RETURNING * INTO v_message;
  RETURN v_message;
END;
$function$

CREATE OR REPLACE FUNCTION public.resubmit_vehicle_listing(p_vehicle_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.vehicles WHERE id = p_vehicle_id AND owner_id = auth.uid()
  ) THEN RAISE EXCEPTION 'Vehicle listing not found'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.vehicle_photos WHERE vehicle_id = p_vehicle_id AND NOT rejected
  ) THEN RAISE EXCEPTION 'Add at least one acceptable vehicle photo before resubmitting'; END IF;

  PERFORM set_config('app.vehicle_resubmission', 'on', true);
  UPDATE public.vehicles
  SET approval_status = 'pending', approval_note = NULL, approved_at = NULL, approved_by = NULL
  WHERE id = p_vehicle_id AND owner_id = auth.uid() AND approval_status = 'rejected';
END;
$function$

CREATE OR REPLACE FUNCTION public.require_approved_driver_history(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_user_id) THEN RAISE EXCEPTION 'Member not found'; END IF;
  IF EXISTS(SELECT 1 FROM public.profiles WHERE id=p_user_id AND role='driver' AND document_listing_visibility<>'public') THEN RAISE EXCEPTION 'This driver listing is private or removed. Contact support after renewing the evidence.'; END IF;
  IF EXISTS(SELECT 1 FROM public.profiles WHERE id=p_user_id AND role='driver') AND NOT EXISTS(SELECT 1 FROM public.driver_platform_history WHERE driver_id=p_user_id AND review_status='approved' AND approved AND expires_at>now() AND proof_url IS NOT NULL AND months_active>0) THEN
    IF EXISTS(SELECT 1 FROM public.driver_platform_history WHERE driver_id=p_user_id AND review_status='pending') THEN RAISE EXCEPTION 'Your platform history is awaiting admin approval. Connections and availability unlock after approval.'; END IF;
    RAISE EXCEPTION 'Submit or renew your recent platform history for admin approval before connecting or changing availability.';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_my_account()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'You must be signed in to delete your account';
  END IF;

  IF public.is_admin() THEN
    RAISE EXCEPTION 'Administrator accounts must be transferred or removed by another administrator';
  END IF;

  -- profiles.id references auth.users(id) ON DELETE CASCADE. The related
  -- listings, applications, conversations, messages, reports and uploads are
  -- also linked with cascading foreign keys.
  DELETE FROM auth.users WHERE id = v_user_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_leave_conversation(p_conversation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_conversation public.conversations%ROWTYPE;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Administrator access required';
  END IF;

  SELECT * INTO v_conversation
  FROM public.conversations
  WHERE id = p_conversation_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Conversation not found';
  END IF;

  IF v_conversation.admin_id = auth.uid() THEN
    RAISE EXCEPTION 'The assigned administrator cannot leave a direct support chat';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.conversation_admins
    WHERE conversation_id = p_conversation_id AND admin_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'You have not joined this conversation';
  END IF;

  IF v_conversation.support_reopened_at IS NOT NULL
     AND v_conversation.support_resolved_at IS NULL
     AND v_conversation.closed_at IS NULL THEN
    RAISE EXCEPTION 'End the support session before leaving this conversation';
  END IF;

  INSERT INTO public.messages (conversation_id, sender_id, content, type, read)
  VALUES (p_conversation_id, auth.uid(), 'An administrator left this conversation.', 'system', false);

  DELETE FROM public.conversation_admins
  WHERE conversation_id = p_conversation_id AND admin_id = auth.uid();

  UPDATE public.conversations
  SET last_message_at = now()
  WHERE id = p_conversation_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_issue_report_warning(p_report_id uuid, p_message text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_report public.reports%ROWTYPE;
  v_warning_id uuid;
  v_warning_count integer;
  v_body text;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Administrator access required'; END IF;
  IF char_length(trim(COALESCE(p_message, ''))) < 3 THEN RAISE EXCEPTION 'A warning message is required'; END IF;

  SELECT * INTO v_report FROM public.reports WHERE id = p_report_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Report not found'; END IF;
  IF v_report.reported_id IS NULL THEN RAISE EXCEPTION 'This report has no reported user'; END IF;

  INSERT INTO public.user_warnings (user_id, report_id, admin_id, message, report_reason, report_description)
  VALUES (v_report.reported_id, v_report.id, auth.uid(), trim(p_message), v_report.reason, v_report.description)
  ON CONFLICT (report_id) DO NOTHING
  RETURNING id INTO v_warning_id;

  SELECT count(*)::integer INTO v_warning_count
  FROM public.user_warnings
  WHERE user_id = v_report.reported_id;

  -- The warning already exists. Complete any earlier partially-finished
  -- moderation action, but do not notify the member a second time.
  IF v_warning_id IS NULL THEN
    UPDATE public.reports SET status = 'resolved' WHERE id = v_report.id;
    RETURN v_warning_count;
  END IF;

  v_body := 'Report: ' || v_report.reason || '. ' ||
    CASE WHEN nullif(trim(COALESCE(v_report.description, '')), '') IS NOT NULL
      THEN 'Details: ' || trim(v_report.description) || '. ' ELSE '' END ||
    'Admin message: ' || trim(p_message) || '. This is warning ' || v_warning_count ||
    '. Three warnings may lead to account suspension.';

  INSERT INTO public.notifications (user_id, type, title, body, data)
  VALUES (
    v_report.reported_id, 'warning', 'Account warning related to a report', v_body,
    jsonb_build_object(
      'report_id', v_report.id,
      'report_reason', v_report.reason,
      'target_type', v_report.target_type,
      'warning_count', v_warning_count
    )
  );

  UPDATE public.reports SET status = 'resolved' WHERE id = v_report.id;
  RETURN v_warning_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_registration_terms()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE policy public.registration_terms_policy;
BEGIN
  SELECT * INTO policy FROM public.registration_terms_policy WHERE singleton;
  IF NEW.raw_user_meta_data -> 'terms_accepted' = 'true'::jsonb AND NEW.raw_user_meta_data ->> 'terms_version' = policy.version THEN
    INSERT INTO public.registration_terms_acceptances(user_id,version,site_name,support_email,support_phone)
    SELECT NEW.id, policy.version,
      COALESCE((SELECT value FROM public.site_settings WHERE key = 'site_name'), 'Drivevell'),
      COALESCE((SELECT value FROM public.site_settings WHERE key = 'admin_contact_email'), ''),
      COALESCE((SELECT value FROM public.site_settings WHERE key = 'admin_contact_phone'), '');
  ELSIF policy.enforce_acceptance THEN
    RAISE EXCEPTION 'Accept the current Terms of Service before registering';
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.enforce_owner_listing_controls()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_limit integer;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN RAISE EXCEPTION 'A listing cannot be transferred to another account'; END IF;
    IF OLD.deleted_at IS NOT NULL THEN RAISE EXCEPTION 'This listing has been deleted and cannot be edited'; END IF;
    IF NEW.deleted_at IS DISTINCT FROM OLD.deleted_at AND current_setting('app.vehicle_delete', true) IS DISTINCT FROM 'on' THEN
      RAISE EXCEPTION 'Use the delete listing action';
    END IF;
  ELSE
    NEW.deleted_at := NULL;
    -- Serialize creates for this owner, including simultaneous browser tabs.
    PERFORM pg_advisory_xact_lock(hashtextextended('owner-listings-' || NEW.owner_id::text, 0));
    SELECT COALESCE((SELECT max_listings FROM public.owner_listing_limits WHERE owner_id = NEW.owner_id), 3) INTO v_limit;
    IF (SELECT count(*) FROM public.vehicles WHERE owner_id = NEW.owner_id AND deleted_at IS NULL) >= v_limit THEN
      RAISE EXCEPTION 'Listing limit reached (% cars). Contact support to request more listings.', v_limit;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_my_vehicle(p_vehicle_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v public.vehicles%ROWTYPE;
BEGIN
  SELECT * INTO v FROM public.vehicles WHERE id = p_vehicle_id FOR UPDATE;
  IF NOT FOUND OR v.owner_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'You can only delete your own listing'; END IF;
  IF v.deleted_at IS NOT NULL THEN RETURN; END IF;
  IF EXISTS (SELECT 1 FROM public.applications WHERE vehicle_id = v.id AND status = 'accepted')
    OR EXISTS (SELECT 1 FROM public.conversations c JOIN public.connections x ON x.id = c.connection_id WHERE c.vehicle_id = v.id AND x.status = 'accepted') THEN
    RAISE EXCEPTION 'End the active connection for this car before deleting its listing. Chat history will remain saved.';
  END IF;
  PERFORM set_config('app.vehicle_delete', 'on', true);
  UPDATE public.vehicles SET deleted_at = now(), status = 'closed' WHERE id = v.id;
  PERFORM set_config('app.vehicle_delete', 'off', true);
  UPDATE public.applications SET status = 'rejected' WHERE vehicle_id = v.id AND status = 'pending';
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_application_to_deleted_vehicle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v public.vehicles%ROWTYPE;
BEGIN
  IF NEW.status IN ('pending', 'accepted') THEN
    SELECT * INTO v FROM public.vehicles WHERE id = NEW.vehicle_id FOR SHARE;
    IF NOT FOUND OR v.deleted_at IS NOT NULL THEN RAISE EXCEPTION 'This listing is no longer available'; END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.request_promotion(p_kind text, p_vehicle_id uuid DEFAULT NULL::uuid)
 RETURNS promotion_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE s public.promotion_settings%ROWTYPE; p public.profiles%ROWTYPE; r public.promotion_requests%ROWTYPE;
BEGIN
  SELECT * INTO p FROM public.profiles WHERE id = auth.uid() FOR UPDATE;
  IF NOT FOUND OR p.role NOT IN ('owner','driver') OR p.is_suspended THEN RAISE EXCEPTION 'A non-suspended member account is required'; END IF;
  SELECT * INTO s FROM public.promotion_settings WHERE id;
  IF NOT s.enabled THEN RAISE EXCEPTION 'Promotions are not currently available'; END IF;
  IF p_kind = 'listing' THEN
    IF NOT EXISTS (SELECT 1 FROM public.vehicles WHERE id = p_vehicle_id AND owner_id = p.id AND deleted_at IS NULL AND approval_status = 'approved' AND status = 'active') THEN RAISE EXCEPTION 'Only your live, approved listing can be promoted'; END IF;
  ELSIF p_kind = 'profile' THEN
    IF p_vehicle_id IS NOT NULL THEN RAISE EXCEPTION 'Choose a profile or a listing, not both'; END IF;
    IF p.role = 'driver' AND NOT p.onboarding_completed THEN RAISE EXCEPTION 'Complete About You before promoting your profile'; END IF;
    IF p.role = 'owner' AND NOT EXISTS (SELECT 1 FROM public.vehicles WHERE owner_id = p.id AND deleted_at IS NULL AND status = 'active' AND approval_status = 'approved') THEN RAISE EXCEPTION 'Publish an approved car before promoting your owner profile'; END IF;
  ELSE RAISE EXCEPTION 'Choose a listing or profile'; END IF;
  UPDATE public.promotion_requests SET status = 'expired' WHERE user_id = p.id AND status = 'active' AND expires_at <= now();
  SELECT * INTO r FROM public.promotion_requests WHERE user_id = p.id AND kind = p_kind AND vehicle_id IS NOT DISTINCT FROM p_vehicle_id AND status IN ('awaiting_payment','pending','active');
  IF FOUND THEN RETURN r; END IF;
  INSERT INTO public.promotion_requests(user_id,kind,vehicle_id,amount,duration_days,payment_method,payment_instructions,terms)
    VALUES (p.id,p_kind,p_vehicle_id,CASE WHEN p_kind = 'listing' THEN s.listing_price ELSE s.profile_price END,s.duration_days,s.payment_method,s.payment_instructions,s.terms) RETURNING * INTO r;
  RETURN r;
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_promotion_payment(p_id uuid, p_reference text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.promotion_requests%ROWTYPE;
BEGIN
  SELECT * INTO r FROM public.promotion_requests WHERE id = p_id FOR UPDATE;
  IF NOT FOUND OR r.user_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Promotion request not found'; END IF;
  IF r.status = 'pending' AND r.payment_reference = trim(p_reference) THEN RETURN; END IF;
  IF r.status <> 'awaiting_payment' THEN RAISE EXCEPTION 'This request has already been submitted'; END IF;
  IF p_reference IS NULL OR length(trim(p_reference)) NOT BETWEEN 3 AND 120 THEN RAISE EXCEPTION 'Enter the payment transaction reference (3–120 characters)'; END IF;
  UPDATE public.promotion_requests SET payment_reference = trim(p_reference), status = 'pending' WHERE id = r.id;
  INSERT INTO public.notifications(user_id,type,title,body,data)
    SELECT id,'system','Promotion payment to review','A member submitted a payment reference. Verify receipt before activating the promotion.',jsonb_build_object('url','/admin?tab=promotions') FROM public.profiles WHERE role = 'admin' AND NOT is_suspended;
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'This payment reference has already been submitted. Contact support if you need help.';
END;
$function$

CREATE OR REPLACE FUNCTION public.review_promotion(p_id uuid, p_action text, p_note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.promotion_requests%ROWTYPE;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Administrator access required'; END IF;
  SELECT * INTO r FROM public.promotion_requests WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Request not found'; END IF;
  IF p_action = 'approve' THEN
    IF r.status <> 'pending' THEN RAISE EXCEPTION 'Only a pending payment can be approved'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.promotion_settings WHERE id AND enabled) THEN RAISE EXCEPTION 'Enable promotions before activation'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = r.user_id AND NOT is_suspended AND (role = 'owner' OR (role = 'driver' AND onboarding_completed))) THEN RAISE EXCEPTION 'This member is not eligible for promotion'; END IF;
    IF r.kind = 'listing' AND NOT EXISTS (SELECT 1 FROM public.vehicles WHERE id = r.vehicle_id AND owner_id = r.user_id AND deleted_at IS NULL AND status = 'active' AND approval_status = 'approved') THEN RAISE EXCEPTION 'The listing must be live and approved'; END IF;
    UPDATE public.promotion_requests SET status = 'active', starts_at = now(), expires_at = now() + make_interval(days => r.duration_days), reviewed_by = auth.uid(), admin_note = nullif(trim(p_note),'') WHERE id = r.id;
  ELSIF p_action IN ('reject','cancel') THEN
    IF (p_action = 'reject' AND r.status NOT IN ('awaiting_payment','pending')) OR (p_action = 'cancel' AND r.status <> 'active') THEN RAISE EXCEPTION 'This request cannot be changed in its current state'; END IF;
    IF length(trim(COALESCE(p_note,''))) < 3 THEN RAISE EXCEPTION 'Add a reason and any refund instructions for the member'; END IF;
    UPDATE public.promotion_requests SET status = CASE WHEN p_action = 'reject' THEN 'rejected' ELSE 'cancelled' END, reviewed_by = auth.uid(), admin_note = trim(p_note) WHERE id = r.id;
  ELSE RAISE EXCEPTION 'Unsupported promotion action'; END IF;
  INSERT INTO public.notifications(user_id,type,title,body,data) VALUES (r.user_id,'system',CASE WHEN p_action = 'approve' THEN 'Promotion activated' ELSE 'Promotion update' END,CASE WHEN p_action = 'approve' THEN 'Your paid promotion is active. See its end date in Promotions.' ELSE p_note END,jsonb_build_object('url','/promotions'));
END;
$function$

CREATE OR REPLACE FUNCTION public.request_connection_before_history_gate(p_recipient_id uuid, p_message text DEFAULT NULL::text, p_vehicle_id uuid DEFAULT NULL::uuid)
 RETURNS connections
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_requester public.profiles%ROWTYPE;
  v_recipient public.profiles%ROWTYPE;
  v_connection public.connections%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF auth.uid() = p_recipient_id THEN RAISE EXCEPTION 'You cannot connect to yourself'; END IF;
  SELECT * INTO v_requester FROM public.profiles WHERE id = auth.uid();
  SELECT * INTO v_recipient FROM public.profiles WHERE id = p_recipient_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Member not found'; END IF;
  IF v_requester.is_suspended OR v_recipient.is_suspended THEN RAISE EXCEPTION 'Suspended accounts cannot create connections'; END IF;
  IF v_requester.role = v_recipient.role OR v_requester.role NOT IN ('driver','owner') OR v_recipient.role NOT IN ('driver','owner') THEN
    RAISE EXCEPTION 'Connections must pair one driver with one car owner';
  END IF;
  IF (v_requester.role = 'driver' AND NOT v_requester.onboarding_completed)
     OR (v_recipient.role = 'driver' AND NOT v_recipient.onboarding_completed) THEN
    RAISE EXCEPTION 'The driver must complete their About You profile before connecting';
  END IF;
  IF v_requester.availability <> 'available' OR v_recipient.availability <> 'available' THEN
    RAISE EXCEPTION 'One of these members is currently unavailable';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.connections
    WHERE status IN ('pending','accepted')
      AND ((requester_id = auth.uid() AND recipient_id = p_recipient_id)
        OR (requester_id = p_recipient_id AND recipient_id = auth.uid()))
  ) THEN RAISE EXCEPTION 'A connection with this member is already pending or active'; END IF;

  INSERT INTO public.connections (requester_id, recipient_id, vehicle_id, message, status)
  VALUES (auth.uid(), p_recipient_id, p_vehicle_id, NULLIF(trim(p_message), ''), 'pending')
  RETURNING * INTO v_connection;
  RETURN v_connection;
END;
$function$

CREATE OR REPLACE FUNCTION public.request_connection(p_recipient_id uuid, p_message text DEFAULT NULL::text, p_vehicle_id uuid DEFAULT NULL::uuid)
 RETURNS connections
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in before connecting'; END IF;
  PERFORM public.require_approved_driver_history(auth.uid());
  IF EXISTS (SELECT 1 FROM public.profiles WHERE id = p_recipient_id AND role = 'driver' AND NOT platform_history_approved) THEN RAISE EXCEPTION 'This driver needs admin-approved platform history before you can connect'; END IF;
  IF p_vehicle_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.vehicles WHERE id = p_vehicle_id AND deleted_at IS NULL AND status = 'active' AND approval_status = 'approved') THEN RAISE EXCEPTION 'This listing is no longer available'; END IF;
  RETURN public.request_connection_before_history_gate(p_recipient_id,p_message,p_vehicle_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.gate_connection_driver_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status IN ('pending','accepted') AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN
    IF TG_TABLE_NAME = 'connections' THEN
      PERFORM public.require_approved_driver_history(NEW.requester_id);
      PERFORM public.require_approved_driver_history(NEW.recipient_id);
    ELSE PERFORM public.require_approved_driver_history(NEW.driver_id);
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_history_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_driver uuid := CASE WHEN TG_OP = 'DELETE' THEN OLD.driver_id ELSE NEW.driver_id END;
  v_internal boolean := current_setting('app.history_transition',true) = 'on';
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('history-' || v_driver::text,0));
  IF TG_OP = 'DELETE' THEN
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = v_driver) THEN RETURN OLD; END IF;
    IF current_setting('app.history_delete_draft',true)='on' AND OLD.review_status='draft' AND OLD.submitted_at IS NULL AND OLD.reviewed_at IS NULL THEN RETURN OLD; END IF;
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'Submitted history is retained. Only unsubmitted draft entries can be removed using the draft action.'; END IF;
    RETURN OLD;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.driver_id IS DISTINCT FROM OLD.driver_id THEN RAISE EXCEPTION 'History cannot be transferred'; END IF;
  IF v_internal THEN RETURN NEW; END IF;
  IF public.is_admin() THEN
    IF TG_OP = 'UPDATE' AND (NEW.approved IS DISTINCT FROM OLD.approved OR NEW.review_status IS DISTINCT FROM OLD.review_status OR NEW.expires_at IS DISTINCT FROM OLD.expires_at OR NEW.proof_url IS DISTINCT FROM OLD.proof_url) THEN
      RAISE EXCEPTION 'Use the approve or reject history action';
    END IF;
    RETURN NEW;
  END IF;
  IF auth.uid() IS DISTINCT FROM v_driver OR NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = v_driver AND role = 'driver' AND NOT is_suspended) THEN RAISE EXCEPTION 'An active driver account is required'; END IF;
  IF EXISTS (SELECT 1 FROM public.driver_platform_history WHERE driver_id = v_driver AND review_status = 'pending') THEN
    RAISE EXCEPTION 'Your platform history is awaiting admin review. You cannot submit or edit it again until it is approved or rejected.';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF EXISTS (SELECT 1 FROM public.driver_platform_history WHERE driver_id = v_driver AND review_status = 'approved' AND expires_at > now()) THEN RAISE EXCEPTION 'Your approved history is still valid. Renewal unlocks when it expires.'; END IF;
    IF NEW.approved OR NEW.review_status <> 'draft' OR NEW.expires_at IS NOT NULL OR NEW.reviewed_at IS NOT NULL OR NEW.submitted_at IS NOT NULL THEN RAISE EXCEPTION 'New history must be an unreviewed draft'; END IF;
    IF (SELECT count(*) FROM public.driver_platform_history WHERE driver_id = v_driver AND review_status = 'draft') >= 5 THEN RAISE EXCEPTION 'Use your existing draft entries (maximum five platforms per submission)'; END IF;
  ELSE
    IF OLD.review_status <> 'draft' THEN RAISE EXCEPTION 'Use Renew or Correct rejected history before changing this proof'; END IF;
    IF NEW.approved IS DISTINCT FROM OLD.approved OR NEW.review_status IS DISTINCT FROM OLD.review_status OR NEW.submitted_at IS DISTINCT FROM OLD.submitted_at OR NEW.reviewed_at IS DISTINCT FROM OLD.reviewed_at OR NEW.expires_at IS DISTINCT FROM OLD.expires_at OR NEW.rejection_reason IS DISTINCT FROM OLD.rejection_reason THEN RAISE EXCEPTION 'Review and expiry fields are server managed'; END IF;
  END IF;
  IF NEW.months_active < 0 OR NEW.months_active > 1200 THEN RAISE EXCEPTION 'Enter valid months of platform activity'; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_document_visibility()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF (TG_OP='INSERT' AND NEW.document_listing_visibility<>'public') OR (TG_OP='UPDATE' AND NEW.document_listing_visibility IS DISTINCT FROM OLD.document_listing_visibility) THEN
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'Only admins can change document-related listing visibility'; END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_evidence_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP='DELETE' THEN
    IF OLD.type IN ('work_history','other_trust_evidence') AND NOT public.is_admin() AND EXISTS(SELECT 1 FROM public.profiles WHERE id=OLD.user_id) THEN RAISE EXCEPTION 'Submitted evidence is retained for review'; END IF;
    RETURN OLD;
  END IF;
  IF TG_OP='UPDATE' AND OLD.type IN ('work_history','other_trust_evidence') AND (NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.vehicle_id IS DISTINCT FROM OLD.vehicle_id OR NEW.type IS DISTINCT FROM OLD.type) THEN RAISE EXCEPTION 'Evidence cannot be transferred'; END IF;
  IF NEW.type NOT IN ('work_history','other_trust_evidence') THEN RETURN NEW; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('evidence-'||NEW.user_id::text,0));
  IF TG_OP='INSERT' AND NOT public.is_admin() AND EXISTS(SELECT 1 FROM public.documents WHERE user_id=NEW.user_id AND type=NEW.type AND vehicle_id IS NOT DISTINCT FROM NEW.vehicle_id) THEN RAISE EXCEPTION 'Use your existing evidence entry instead of creating another submission'; END IF;
  IF public.is_admin() THEN
    IF NEW.verified AND (TG_OP='INSERT' OR NOT OLD.verified) THEN NEW.reviewed_at:=now(); NEW.expiry_date:=(now()+interval '6 months')::date; END IF;
  ELSIF TG_OP='UPDATE' THEN
    IF NOT OLD.rejected AND (NOT OLD.verified OR OLD.expiry_date>=current_date) THEN RAISE EXCEPTION 'Evidence is locked until rejected or expired'; END IF;
    IF NEW.expiry_date IS DISTINCT FROM OLD.expiry_date OR NEW.reviewed_at IS DISTINCT FROM OLD.reviewed_at THEN RAISE EXCEPTION 'Expiry is server managed'; END IF;
    IF NEW.file_url IS NOT DISTINCT FROM OLD.file_url THEN RAISE EXCEPTION 'Choose updated proof before resubmitting'; END IF;
  ELSIF NEW.expiry_date IS NOT NULL OR NEW.reviewed_at IS NOT NULL THEN RAISE EXCEPTION 'Expiry is server managed';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.prepare_history_renewal(p_id uuid)
 RETURNS driver_platform_history
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE h public.driver_platform_history%ROWTYPE;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('history-' || auth.uid()::text,0));
  SELECT * INTO h FROM public.driver_platform_history WHERE id = p_id AND driver_id = auth.uid() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'History not found'; END IF;
  IF EXISTS (SELECT 1 FROM public.driver_platform_history WHERE driver_id = auth.uid() AND review_status = 'pending') THEN RAISE EXCEPTION 'Wait for admin review before editing or resubmitting'; END IF;
  IF h.review_status = 'draft' THEN RETURN h; END IF;
  IF h.review_status <> 'rejected' AND NOT (h.review_status = 'approved' AND h.expires_at <= now()) THEN RAISE EXCEPTION 'Renewal is available only after expiry or rejection'; END IF;
  INSERT INTO public.platform_history_versions(history_id,driver_id,snapshot) VALUES(h.id,h.driver_id,to_jsonb(h));
  PERFORM set_config('app.history_transition','on',true);
  UPDATE public.driver_platform_history SET review_status='draft',approved=false,proof_url=NULL,submitted_at=NULL,rejection_reason=NULL WHERE id=h.id RETURNING * INTO h;
  PERFORM set_config('app.history_transition','off',true);
  RETURN h;
END;
$function$

CREATE OR REPLACE FUNCTION public.remove_history_draft(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('history-' || auth.uid()::text,0));
  IF EXISTS (SELECT 1 FROM public.driver_platform_history WHERE driver_id=auth.uid() AND review_status='pending') THEN RAISE EXCEPTION 'Wait for admin review'; END IF;
  -- Submitted/renewal records must remain available for review and disputes.
  IF NOT EXISTS (SELECT 1 FROM public.driver_platform_history WHERE id=p_id AND driver_id=auth.uid() AND review_status='draft' AND reviewed_at IS NULL AND submitted_at IS NULL) THEN RAISE EXCEPTION 'Only a new unsubmitted draft can be removed'; END IF;
  PERFORM set_config('app.history_delete_draft','on',true);
  DELETE FROM public.driver_platform_history WHERE id=p_id;
  PERFORM set_config('app.history_delete_draft','off',true);
END;
$function$

CREATE OR REPLACE FUNCTION public.review_platform_history(p_id uuid, p_decision text, p_reason text DEFAULT NULL::text, p_submitted_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE h public.driver_platform_history%ROWTYPE;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Administrator access required'; END IF;
  SELECT * INTO h FROM public.driver_platform_history WHERE id=p_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'History not found'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('history-' || h.driver_id::text,0));
  SELECT * INTO h FROM public.driver_platform_history WHERE id=p_id FOR UPDATE;
  IF p_submitted_at IS NULL OR h.submitted_at IS DISTINCT FROM p_submitted_at THEN RAISE EXCEPTION 'This submission changed. Refresh before reviewing'; END IF;
  IF h.review_status = p_decision THEN RETURN; END IF;
  IF h.review_status <> 'pending' THEN RAISE EXCEPTION 'Only a pending submission can be reviewed'; END IF;
  IF p_decision NOT IN ('approved','rejected') THEN RAISE EXCEPTION 'Choose approve or reject'; END IF;
  IF p_decision='rejected' AND length(trim(COALESCE(p_reason,''))) < 3 THEN RAISE EXCEPTION 'Give a clear rejection reason'; END IF;
  IF NULLIF(trim(h.proof_url),'') IS NULL OR h.months_active < 1 THEN RAISE EXCEPTION 'This submission is missing proof or activity'; END IF;
  PERFORM set_config('app.history_transition','on',true);
  UPDATE public.driver_platform_history SET review_status=p_decision,approved=p_decision='approved',reviewed_at=now(),
    expires_at=CASE WHEN p_decision='approved' THEN now()+interval '6 months' ELSE expires_at END,
    rejection_reason=CASE WHEN p_decision='rejected' THEN trim(p_reason) END WHERE id=p_id;
  PERFORM set_config('app.history_transition','off',true);
  INSERT INTO public.notifications(user_id,type,title,body,data) VALUES(h.driver_id,'trust','Platform history '||p_decision,
    CASE WHEN p_decision='approved' THEN 'Your '||h.platform||' history is approved for six months. View its expiry date and countdown in Platform history.' ELSE trim(p_reason)||' You can now correct and resubmit this proof.' END,
    jsonb_build_object('path','/onboarding','history_id',h.id));
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_document_listing_action(p_user_id uuid, p_vehicle_id uuid, p_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Administrator access required'; END IF;
  IF p_action NOT IN ('private','deleted','public') THEN RAISE EXCEPTION 'Choose private, delete or restore'; END IF;
  IF p_vehicle_id IS NULL THEN
    IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_user_id AND role='driver') THEN RAISE EXCEPTION 'Driver listing not found'; END IF;
    IF p_action='public' AND NOT EXISTS(SELECT 1 FROM public.driver_platform_history WHERE driver_id=p_user_id AND review_status='approved' AND approved AND expires_at>now() AND proof_url IS NOT NULL AND months_active>0) THEN RAISE EXCEPTION 'Submit or renew platform history before restoring this listing'; END IF;
    UPDATE public.profiles SET document_listing_visibility=p_action WHERE id=p_user_id;
  ELSE
    IF NOT EXISTS(SELECT 1 FROM public.vehicles WHERE id=p_vehicle_id AND owner_id=p_user_id AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Vehicle listing not found'; END IF;
    IF p_action='public' AND EXISTS(SELECT 1 FROM public.documents WHERE vehicle_id=p_vehicle_id AND expiry_date<current_date AND type IN ('work_history','other_trust_evidence')) THEN RAISE EXCEPTION 'Review renewed evidence before restoring this listing'; END IF;
    UPDATE public.vehicles SET document_listing_visibility=p_action WHERE id=p_vehicle_id;
  END IF;
  INSERT INTO public.notifications(user_id,type,title,body,data) VALUES(p_user_id,'document_listing','Listing visibility updated',
    CASE p_action WHEN 'public' THEN 'Support restored your listing to public visibility.' WHEN 'private' THEN 'Support made your listing private because its documents expired. Update your evidence and contact support to restore it.' ELSE 'Support removed your listing from public discovery because its documents expired. Your account and chat history remain saved. Update your evidence and contact support.' END,
    jsonb_build_object('path',CASE WHEN p_vehicle_id IS NULL THEN '/onboarding' ELSE '/vehicles/'||p_vehicle_id::text||'/edit' END));
END;
$function$

CREATE OR REPLACE FUNCTION public.process_document_expiry_reminders()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE d record; v_milestone integer; v_id uuid; v_body text; v_count integer:=0;
BEGIN
  -- Refresh cached badges; permission checks also compare expiry in real time.
  PERFORM set_config('app.profile_system_update','on',true);
  UPDATE public.profiles p SET platform_history_approved=false,platform_history_submitted=false
    WHERE p.role='driver' AND p.platform_history_approved AND NOT EXISTS(SELECT 1 FROM public.driver_platform_history h WHERE h.driver_id=p.id AND h.review_status='approved' AND h.approved AND h.expires_at>now());
  UPDATE public.profiles SET is_verified=false,verification_status=CASE WHEN platform_history_submitted THEN 'pending' ELSE 'unverified' END WHERE role='driver' AND NOT platform_history_approved AND is_verified;
  PERFORM set_config('app.profile_system_update','off',true);
  -- Cancel mail not yet sent for superseded documents or submitted renewals.
  UPDATE reminder_private.deliveries q SET email_status='cancelled' WHERE q.email_status='queued' AND NOT EXISTS(
    SELECT 1 FROM public.document_expiry_items() current_doc WHERE current_doc.source_key=q.source_key AND current_doc.expires_at=q.expires_at AND current_doc.review_status<>'pending'
      AND q.milestone=CASE WHEN current_doc.expires_at<=now() THEN 0 WHEN current_doc.expires_at<=now()+interval '1 day' THEN 1 WHEN current_doc.expires_at<=now()+interval '7 days' THEN 7 ELSE 30 END);
  FOR d IN SELECT * FROM public.document_expiry_items() WHERE expires_at<=now()+interval '30 days' AND review_status<>'pending' LOOP
    v_milestone:=CASE WHEN d.expires_at<=now() THEN 0 WHEN d.expires_at<=now()+interval '1 day' THEN 1 WHEN d.expires_at<=now()+interval '7 days' THEN 7 ELSE 30 END;
    v_id:=NULL;
    INSERT INTO reminder_private.deliveries(source_key,user_id,expires_at,milestone,label,path) VALUES(d.source_key,d.user_id,d.expires_at,v_milestone,d.label,d.path)
      ON CONFLICT(source_key,expires_at,milestone) DO NOTHING RETURNING id INTO v_id;
    IF v_id IS NULL THEN CONTINUE; END IF;
    v_body:=CASE WHEN v_milestone=0 THEN d.label||' expired. Submit updated proof now to avoid your listing being made private or removed by an administrator. If you have uploaded a draft, remember to submit it for review.'
      ELSE d.label||' expires on '||to_char(d.expires_at AT TIME ZONE 'Africa/Nairobi','DD Mon YYYY HH24:MI')||' EAT. Prepare your latest proof. Renewal opens when the current approval expires; submit it promptly then to avoid your listing being made private or removed.' END;
    INSERT INTO public.notifications(user_id,type,title,body,data) VALUES(d.user_id,'document_expiry',CASE WHEN v_milestone=0 THEN 'Document expired — update required' ELSE 'Document expiry reminder' END,v_body,jsonb_build_object('path',d.path,'expires_at',d.expires_at,'source_key',d.source_key));
    IF v_milestone=0 THEN
      INSERT INTO public.notifications(user_id,type,title,body,data) SELECT id,'document_expiry','Expired document needs attention',d.full_name||': '||d.label||' has expired. Review the listing and contact the member.',jsonb_build_object('path','/admin?tab=expired') FROM public.profiles WHERE role='admin' AND NOT is_suspended;
    END IF;
    v_count:=v_count+1;
  END LOOP;
  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.gate_document_listing_visibility()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status IN ('pending','accepted') AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN
    IF NEW.vehicle_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.vehicles WHERE id=NEW.vehicle_id AND document_listing_visibility<>'public') THEN RAISE EXCEPTION 'This listing is private or removed and cannot receive new connections'; END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.dispatch_document_reminder_email()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE q reminder_private.deliveries%ROWTYPE; cfg reminder_private.email_config%ROWTYPE;
  v_key text; v_name text; v_email text; v_support text; v_subject text; v_text text; v_request bigint;
  r record;
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtextextended('document-reminder-mail-worker',0)) THEN RETURN; END IF;
  -- Reconcile async HTTP responses without logging recipient addresses or tokens.
  FOR r IN SELECT queued.id,queued.attempts,queued.first_attempt_at,response.status_code,response.timed_out,response.error_msg
    FROM reminder_private.deliveries queued JOIN net._http_response response ON response.id=queued.request_id WHERE queued.email_status='sending'
  LOOP
    IF r.status_code BETWEEN 200 AND 299 THEN
      UPDATE reminder_private.deliveries SET email_status='accepted',last_error=NULL WHERE id=r.id;
    ELSIF (r.status_code IS NULL OR r.status_code=429 OR r.status_code>=500) AND r.attempts<5 AND r.first_attempt_at>now()-interval '23 hours' THEN
      UPDATE reminder_private.deliveries SET email_status='queued',next_attempt_at=now()+make_interval(mins=>power(2,r.attempts)::integer),last_error='Temporary email provider error; retry scheduled' WHERE id=r.id;
    ELSE
      UPDATE reminder_private.deliveries SET email_status='failed',last_error='Email provider rejected the request or retries exhausted; review sender configuration' WHERE id=r.id;
    END IF;
  END LOOP;
  -- A missing HTTP response is uncertain, not a successful send. The same
  -- idempotency key is reused only inside the provider's 24-hour dedup window.
  UPDATE reminder_private.deliveries SET email_status=CASE WHEN attempts<5 AND first_attempt_at>now()-interval '23 hours' THEN 'queued' ELSE 'failed' END,
    last_error='Email response was not confirmed',next_attempt_at=now()
    WHERE email_status='sending' AND next_attempt_at<now()-interval '10 minutes';
  SELECT * INTO cfg FROM reminder_private.email_config WHERE id;
  IF NOT cfg.enabled OR NULLIF(cfg.from_email,'') IS NULL THEN RETURN; END IF;
  SELECT decrypted_secret INTO v_key FROM vault.decrypted_secrets WHERE name='document_reminder_resend_key' LIMIT 1;
  IF NULLIF(v_key,'') IS NULL THEN RETURN; END IF;

  -- One request/minute is intentionally below provider burst limits. The queue
  -- survives restarts and concurrent workers claim rows with SKIP LOCKED.
  SELECT * INTO q FROM reminder_private.deliveries WHERE email_status='queued' AND next_attempt_at<=now() ORDER BY created_at LIMIT 1 FOR UPDATE SKIP LOCKED;
  IF NOT FOUND THEN RETURN; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.document_expiry_items() d WHERE d.source_key=q.source_key AND d.expires_at=q.expires_at AND d.review_status<>'pending'
    AND q.milestone=CASE WHEN d.expires_at<=now() THEN 0 WHEN d.expires_at<=now()+interval '1 day' THEN 1 WHEN d.expires_at<=now()+interval '7 days' THEN 7 ELSE 30 END) THEN
    UPDATE reminder_private.deliveries SET email_status='cancelled' WHERE id=q.id; RETURN;
  END IF;
  IF q.first_attempt_at<now()-interval '23 hours' THEN
    UPDATE reminder_private.deliveries SET email_status='failed',last_error='Uncertain delivery is outside the safe retry window; check provider logs before retrying' WHERE id=q.id; RETURN;
  END IF;
  -- Supabase Auth is the authoritative registered email, never a public profile
  -- field or an address supplied in a document upload request.
  SELECT email INTO v_email FROM auth.users WHERE id=q.user_id;
  IF NULLIF(v_email,'') IS NULL THEN
    UPDATE reminder_private.deliveries SET email_status='failed',last_error='No registered email is available' WHERE id=q.id; RETURN;
  END IF;
  IF q.email_payload IS NOT NULL AND q.email_payload->'to' IS DISTINCT FROM jsonb_build_array(v_email) THEN
    UPDATE reminder_private.deliveries SET email_status='cancelled',last_error='Registered email changed after the first attempt' WHERE id=q.id; RETURN;
  END IF;
  IF q.email_payload IS NULL THEN
    SELECT COALESCE(NULLIF(value,''),'Drivevell') INTO v_name FROM public.site_settings WHERE key='site_name';
    v_name:=COALESCE(v_name,'Drivevell');
    SELECT value INTO v_support FROM public.site_settings WHERE key='admin_contact_email';
    v_subject:=v_name||CASE WHEN q.milestone=0 THEN ': update your expired platform evidence' ELSE ': your platform evidence expires soon' END;
    v_text:=v_name||E' document reminder\n\n'||q.label||' expires on '||to_char(q.expires_at AT TIME ZONE 'Africa/Nairobi','DD Mon YYYY HH24:MI')||E' EAT.\n\n'||
      CASE WHEN q.milestone=0 THEN 'Your evidence has expired. Please upload and submit updated proof now.' ELSE 'Prepare your latest proof. Renewal unlocks when the current approval expires; submit your update promptly then.' END||
      E'\n\nKeep your documents up to date to avoid your listing being made private or removed by an administrator. Uploading a draft alone does not submit it for review. If your renewal is already pending, wait for the review decision.'||
      E'\n\nOpen your account: '||rtrim(cfg.site_url,'/')||q.path||E'\nSupport: '||COALESCE(v_support,rtrim(cfg.site_url,'/')||'/contact')||
      E'\n\nThis is an account-service reminder, not a marketing email. Do not send identity documents by email.';
    q.email_payload:=jsonb_build_object('from',regexp_replace(v_name,'[<>"\r\n]','','g')||' <'||cfg.from_email||'>','to',jsonb_build_array(v_email),'subject',v_subject,'text',v_text);
    IF NULLIF(v_support,'') IS NOT NULL THEN q.email_payload:=q.email_payload||jsonb_build_object('reply_to',v_support); END IF;
  END IF;
  SELECT net.http_post(url:='https://api.resend.com/emails',body:=q.email_payload,
    headers:=jsonb_build_object('Authorization','Bearer '||v_key,'Content-Type','application/json','Idempotency-Key','document-reminder/'||q.id::text),timeout_milliseconds:=10000) INTO v_request;
  UPDATE reminder_private.deliveries SET email_status='sending',request_id=v_request,attempts=attempts+1,email_payload=q.email_payload,
    first_attempt_at=COALESCE(first_attempt_at,now()),next_attempt_at=now() WHERE id=q.id;
END;
$function$
